(function(){'use strict';
const B=window.CrmBaseline,KEY='crm-diploma-prototype-v1';
const seed=[
{id:'DEMO-01',customer:'Northstar Studio',title:'Duplicate invoice',channel:'Email',date:'19 Oct 2026',text:'Customer: I received invoice INV-104 twice. Has my card been charged twice?\nAgent: I can see one completed payment. The second email is a duplicate invoice notice.\nCustomer: Please confirm that I do not need to pay again.\nAgent: You do not need to pay again. I will send the corrected billing statement today.',review:null},
{id:'DEMO-02',customer:'Alpine Learning',title:'Team onboarding',channel:'Chat',date:'18 Oct 2026',text:'Customer: Three colleagues have not received their onboarding invitations.\nAgent: Please check the spam folder. I can resend the invitations.\nCustomer: We checked and there are no messages there.\nAgent: I will resend the invitations after this chat. No training date has been agreed yet.',review:null},
{id:'DEMO-03',customer:'Harbor Supply',title:'API access issue',channel:'Call transcript',date:'18 Oct 2026',text:'Customer: Our integration returns an authentication error after the token change.\nAgent: Does the new token have read access to customer records?\nCustomer: I have not checked its permissions.\nAgent: Please check the read permission first. We have not confirmed the cause yet.',review:null},
{id:'DEMO-04',customer:'Cedar Labs',title:'Subscription renewal',channel:'Email',date:'17 Oct 2026',text:'Customer: We would like to cancel the renewal but keep access until the current term ends.\nAgent: I will forward the cancellation request to billing. It has not been processed yet.\nCustomer: Please send confirmation when it is processed.',review:null},
{id:'DEMO-05',customer:'Orion Design',title:'Analysis needs a retry',channel:'Chat',date:'17 Oct 2026',text:'Customer: Can we arrange onboarding for our support team?\nAgent: Please send the number of users and preferred dates.\nCustomer: There will be six users. We have not selected a date.',review:null,failed:true}
];
let records=[],selected='DEMO-01',busy=false;
const $=id=>document.getElementById(id);
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function status(r){return r.failed?'failed':r.review?.decision||'unreviewed';}
function statusLabel(r){return {failed:'Analysis failed',unreviewed:'Needs review',approved:'Approved',rejected:'Rejected'}[status(r)];}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(records));}catch(e){notice('Browser storage is unavailable. Changes remain in this tab only.');}}
function notice(s){$('notice').textContent=s;}
function current(){return records.find(x=>x.id===selected);}
function filtered(){const q=$('search').value.toLowerCase().trim(),s=$('status-filter').value;return records.filter(r=>(s==='all'||status(r)===s)&&(!q||[r.customer,r.title,r.text,...(r.result?.topics||[])].join(' ').toLowerCase().includes(q)));}
function list(){const rows=filtered(),host=$('interaction-list');host.replaceChildren();$('record-count').textContent=`${rows.length} records`;
 if(!rows.length){host.append(el('p','empty','No interactions match. Change the search or review filter.'));return;}
 for(const r of rows){const btn=el('button',`interaction-item${r.id===selected?' selected':''}`);btn.setAttribute('aria-label',`${r.customer}: ${r.title}`);btn.setAttribute('aria-pressed',r.id===selected?'true':'false');btn.append(el('strong','',r.customer),el('span','sub',r.title));const m=el('span','meta');m.append(el('span',`status ${status(r)}`,statusLabel(r)),el('span','',r.channel));btn.append(m);btn.addEventListener('click',()=>{selected=r.id;render();});host.append(btn);}}
function button(text,cls,fn){const b=el('button',cls,text);b.addEventListener('click',fn);return b;}
function render(){list();detail();overview();}
function detail(){const host=$('detail');host.replaceChildren();const r=current();if(!r){host.append(el('p','empty','Select an interaction to inspect.'));return;}
 const head=el('header','detail-head'),ht=el('div');ht.append(el('h2','',r.title),el('p','',`${r.customer} / ${r.channel} / ${r.date}`));head.append(ht,el('span',`status ${status(r)}`,statusLabel(r)));host.append(head);
 const grid=el('div','detail-grid'),conversation=el('section','conversation');conversation.setAttribute('aria-label','Source conversation');const sh=el('div','section-head');sh.append(el('h3','','Source conversation'),el('span','',r.id));conversation.append(sh);
 let turns;try{turns=B.parseTurns(r.text);}catch(e){turns=[];conversation.append(el('p','error',e.message));}
 for(const t of turns){const a=el('article','turn');a.id=t.id;const sp=el('div','speaker',t.speaker);sp.append(el('span','',`Turn ${t.sequence}`));a.append(sp,el('p','',t.text));conversation.append(a);}
 const analysis=el('section','analysis');analysis.setAttribute('aria-label','Analysis and human review');analysis.append(el('h3','','Interaction analysis'),el('p','intro','Keyword / extractive baseline. Check the source before approval.'));
 const run=button(busy?'Analysing…':r.failed?'Retry analysis':'Run analysis','primary',()=>runAnalysis(r));run.disabled=busy;run.id='run-analysis';analysis.append(run);
 if(r.failed){analysis.append(el('p','error','Example failure: analysis was interrupted. Retry to run the local baseline. No result has been approved.'));}
 else if(r.result){analysis.append(el('h3','','Topics'));const tags=el('div','tags');for(const t of r.result.topics)tags.append(el('span','tag',t));analysis.append(tags,el('h3','','Extractive summary'),el('p','summary',r.result.summary));
 const refs=el('div','source-refs');for(const ref of r.result.sourceRefs){const n=ref.split('-')[1];const b=button(`Source ${n}`,'source-button',()=>{const turn=$(ref);turn?.scrollIntoView({behavior:'smooth',block:'center'});turn?.classList.add('highlight');turn?.setAttribute('tabindex','-1');turn?.focus({preventScroll:true});setTimeout(()=>turn?.classList.remove('highlight'),1800);});b.setAttribute('aria-label',`Inspect source turn ${n}`);refs.append(b);}analysis.append(refs);
 const lab=el('label','','Reviewed summary');lab.htmlFor='review-text';const ta=el('textarea');ta.id='review-text';ta.value=r.review?.text??r.result.summary;ta.maxLength=3000;analysis.append(lab,ta);
 const actions=el('div','review-actions');actions.append(button('Approve review','approve',()=>review(r,'approved')),button('Reject','reject',()=>review(r,'rejected')));analysis.append(actions);
 if(r.review)analysis.append(el('p','help',`${r.review.decision==='approved'?'Approved':'Rejected'} by demo reviewer. Raw analysis is preserved.`));
 const raw=el('details','raw-details');raw.append(el('summary','','Raw result and provenance'),el('p','',`Method: ${r.result.method}. No learned model.`),el('p','',`SHA-256: ${r.result.sourceHash}`),el('p','',`Raw output: ${r.result.summary}`));analysis.append(raw);
 }else analysis.append(el('div','empty-analysis','Run analysis to generate topic labels and an extractive summary. The source text stays unchanged.'));
 grid.append(conversation,analysis);host.append(grid);const footer=el('div','footer-actions');footer.append(el('p','','Fictional example. Human review is a separate step.'),button('Export selected JSON','export',()=>exportRecord(r)));host.append(footer);
}
async function runAnalysis(r){if(busy)return;busy=true;r.failed=false;notice('Running the local baseline…');detail();try{await new Promise(resolve=>setTimeout(resolve,450));const result=await B.analyse(r.text);r.result=result;r.review=null;r.failed=false;notice('Analysis complete. Inspect the source and review the result.');}catch(e){r.failed=true;notice('Analysis failed. Check the text format and retry.');}finally{busy=false;persist();render();}}
function review(r,decision){const text=$('review-text').value.trim();if(!text){notice('Enter a reviewed summary before saving a decision.');$('review-text').focus();return;}r.review={decision,text,reviewer:'demo-reviewer',createdAt:new Date().toISOString()};persist();render();notice(decision==='approved'?'Review approved. The raw summary is preserved.':'Review rejected. The raw summary is preserved.');}
function exportRecord(r){const payload={prototype:true,synthetic:true,customer:r.customer,interaction:{id:r.id,channel:r.channel,sourceText:r.text},analysis:r.result||null,review:r.review||null,limitations:'Local baseline demo. No server-side permissions or trained model.'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${r.id}-analysis.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Selected fictional interaction exported as JSON.');}
function overview(){const host=$('overview-content');host.replaceChildren();const table=el('table','counts'),tr=el('tr');tr.append(el('th','','Review state'),el('th','','Fictional records'));table.append(tr);for(const [s,label]of Object.entries({unreviewed:'Needs review',approved:'Approved',rejected:'Rejected',failed:'Analysis failed'})){const row=el('tr');row.append(el('td','',label),el('td','',String(records.filter(r=>status(r)===s).length)));table.append(row);}host.append(table);}
function view(which){for(const n of ['interaction','overview','method'])$(n+'-view').hidden=n!==which;for(const n of ['interactions','overview','method']){const b=$('nav-'+n),active=(n==='interactions'?'interaction':n)===which;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}}
$('nav-interactions').addEventListener('click',()=>view('interaction'));$('nav-overview').addEventListener('click',()=>{overview();view('overview');});$('nav-method').addEventListener('click',()=>view('method'));
function refilter(){const rows=filtered();if(!rows.some(r=>r.id===selected))selected=rows[0]?.id||null;render();}
$('search').addEventListener('input',refilter);$('status-filter').addEventListener('change',refilter);
$('new-interaction').addEventListener('click',()=>{$('capture-form').reset();$('form-error').textContent='';$('capture-dialog').showModal();$('customer-name').focus();});
for(const id of ['close-dialog','cancel-dialog'])$(id).addEventListener('click',()=>$('capture-dialog').close());
$('capture-form').addEventListener('submit',e=>{e.preventDefault();const customer=$('customer-name').value.trim(),title=$('interaction-title').value.trim(),text=$('transcript-input').value;try{if(!customer)throw new Error('Enter a customer name.');if(!title)throw new Error('Enter an interaction title.');B.parseTurns(text);const r={id:'DEMO-'+Date.now().toString(36),customer,title,text,channel:$('channel').value,date:'New fictional example',review:null};records.unshift(r);selected=r.id;persist();$('search').value='';$('status-filter').value='all';$('capture-dialog').close();view('interaction');render();notice('Interaction saved locally. Run analysis to review it.');}catch(err){$('form-error').textContent=err.message;}});
$('reset-demo').addEventListener('click',async()=>{if(!confirm('Reset only this prototype’s fictional examples and local reviews?'))return;records=structuredClone(seed);for(const r of records.slice(0,2))r.result=await B.analyse(r.text);selected=records[0].id;persist();render();view('interaction');notice('Fictional examples reset.');});
async function init(){try{const stored=JSON.parse(localStorage.getItem(KEY)||'null');records=Array.isArray(stored)&&stored.every(r=>r.id&&r.text&&r.customer)?stored:structuredClone(seed);}catch(e){records=structuredClone(seed);}if(!records.length)records=structuredClone(seed);for(const r of records.slice(0,2))if(!r.result&&!r.failed)r.result=await B.analyse(r.text);selected=records[0].id;persist();render();}
init().catch(()=>{records=structuredClone(seed);render();notice('Initial analysis is unavailable. Run the prototype on localhost and retry.');});
})();
